import java.util.Scanner;

public class Main {
    static long[] b = new long[20];

    static long recurse(long val, long level) {
        long quotient = val / b[(int) level];
        long remainder = val % b[(int) level];
        if (remainder == 0)
            return quotient * level;
        else
            return quotient * level + Math.min(recurse(remainder, level - 1),
                    level + recurse(b[(int) level] - remainder, level - 1));
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        for (int i = 1; i <= 17; ++i)
            b[i] = b[i - 1] * 10 + 1;
        long n = sc.nextLong();
        long count = 0, temp_n = n;
        while (temp_n != 0) {
            temp_n /= 10;
            ++count;
        }
        System.out.println(recurse(n, count + 2));
        sc.close();
    }
}
